-- =====================================================================
-- ตากหลาดนัด — Migration ฐานข้อมูล (MariaDB 10.5+)
-- ---------------------------------------------------------------------
-- ระบบตลาดนัดทั้งจังหวัดตาก (9 อำเภอ): สร้างตาราง อัปเกรดฐานข้อมูลเดิม
-- และใส่ข้อมูลตัวอย่างที่สมจริง (ตลาด แผง ร้านค้า รอบตลาด การจอง)
--
-- รันซ้ำได้อย่างปลอดภัย:
--   * ใช้ CREATE TABLE IF NOT EXISTS / ADD COLUMN IF NOT EXISTS
--   * ข้อมูลอ้างอิง (อำเภอ, ประเภทสินค้า) ไม่เขียนทับค่าที่ผู้ดูแลแก้ไว้
--   * ข้อมูลตัวอย่างใส่ครั้งเดียว เมื่อยังไม่มีตลาดรหัส TAK-MU-01
--   * ไม่มีคำสั่งลบข้อมูลเดิม
--
-- วิธีใช้:  mysql -h <host> -u <user> -p <database> < migration.sql
--           หรือนำเข้า (Import) ทั้งไฟล์ผ่านหน้าจัดการฐานข้อมูล ในครั้งเดียว
--           (ต้องรันทั้งไฟล์ใน session เดียว เพราะใช้ตารางชั่วคราว)
--
-- หมายเหตุ: server.js ไม่สร้างตารางเอง — schema อยู่ที่ไฟล์นี้ที่เดียว
-- =====================================================================

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 1. districts — อำเภอในจังหวัดตาก (รหัสตามกรมการปกครอง 6301–6309)
--    latitude/longitude = จุดกึ่งกลางโดยประมาณ ใช้จัดแผนที่
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS districts (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  code CHAR(4) NOT NULL,
  name_th VARCHAR(100) NOT NULL,
  name_en VARCHAR(100) NULL,
  latitude DECIMAL(9,6) NOT NULL,
  longitude DECIMAL(9,6) NOT NULL,
  sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  UNIQUE KEY uq_districts_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 2. categories — ประเภทสินค้ามาตรฐาน ใช้กรองร้านทั้งจังหวัด
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS categories (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  icon VARCHAR(16) NULL,
  sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  UNIQUE KEY uq_categories_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 3. users — บัญชีผู้ใช้ (login ด้วยอีเมล; phone เป็นข้อมูลติดต่อ)
--    role: shop (ค่าเริ่มต้น) | admin (ผู้ดูแลตลาดระดับจังหวัด)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(255) NOT NULL,
  phone VARCHAR(20) NULL,
  password_hash VARCHAR(255) NOT NULL,
  role VARCHAR(20) NOT NULL DEFAULT 'shop',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  UNIQUE KEY uq_users_email (email),
  UNIQUE KEY uq_users_phone (phone)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 4. shops — ข้อมูลร้านค้า (หนึ่งบัญชีหนึ่งร้าน)
--    category_id → categories; คอลัมน์ category (ข้อความ) เป็นของเวอร์ชันเก่า
--    เก็บไว้เพื่อไม่ให้ข้อมูลเดิมหาย ระบบไม่ได้ใช้แล้ว
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS shops (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  user_id INT UNSIGNED NOT NULL,
  shop_name VARCHAR(150) NOT NULL,
  category_id INT UNSIGNED NULL,
  category VARCHAR(100) NULL,
  description TEXT NULL,
  contact_name VARCHAR(100) NULL,
  contact_phone VARCHAR(20) NULL,
  social_url VARCHAR(255) NULL,
  image_url VARCHAR(255) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_shops_user (user_id),
  INDEX idx_shops_category (category),
  INDEX idx_shops_category_id (category_id),
  CONSTRAINT fk_shops_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_shops_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 5. markets — ตลาด (หลายตลาด ทุกอำเภอ)
--    market_type: weekly ตลาดนัด | morning ตลาดเช้า/ตลาดสด | evening ตลาดเย็น
--                 walking_street ถนนคนเดิน | border ตลาดชายแดน | community ตลาดชุมชน
--    open_days  : วันเปิดประจำ "0,6" (0 = อาทิตย์ … 6 = เสาร์)
--    latitude/longitude ต้องอยู่ในจังหวัดตาก (ตรวจที่ server.js)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS markets (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(20) NULL,
  market_name VARCHAR(150) NOT NULL,
  district_id INT UNSIGNED NULL,
  subdistrict VARCHAR(100) NULL,
  address VARCHAR(500) NULL,
  latitude DECIMAL(9,6) NULL,
  longitude DECIMAL(9,6) NULL,
  market_type VARCHAR(30) NOT NULL DEFAULT 'weekly',
  open_days VARCHAR(20) NULL,
  open_time TIME NULL,
  close_time TIME NULL,
  description TEXT NULL,
  organizer VARCHAR(150) NULL,
  contact_phone VARCHAR(20) NULL,
  image_url VARCHAR(255) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_markets_code (code),
  INDEX idx_markets_district (district_id, is_active),
  CONSTRAINT fk_markets_district FOREIGN KEY (district_id) REFERENCES districts(id) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 6. market_events — รอบ/วันที่จัดตลาด
--    status: scheduled | open | closed | cancelled
--    open_time/close_time เป็น NULL ได้ เพื่อใช้เวลาของตลาดแทน
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS market_events (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  market_id INT UNSIGNED NOT NULL,
  event_name VARCHAR(150) NOT NULL,
  event_date DATE NOT NULL,
  open_time TIME NULL,
  close_time TIME NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'scheduled',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_events_market_date (market_id, event_date),
  INDEX idx_events_date_status (event_date, status),
  CONSTRAINT fk_events_market FOREIGN KEY (market_id) REFERENCES markets(id) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 7. booths — แผงขาย
--    map_x/map_y = ตำแหน่งบนผังเป็นสัดส่วน 0–100
--    status: available | unavailable | maintenance
--    zone = ชื่อโซน เช่น "โซน A · อาหารปรุงสำเร็จ"; has_electricity/has_roof = สิ่งอำนวยความสะดวก
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS booths (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  market_id INT UNSIGNED NOT NULL,
  booth_code VARCHAR(30) NOT NULL,
  zone VARCHAR(50) NULL,
  map_x DECIMAL(8,3) NULL,
  map_y DECIMAL(8,3) NULL,
  width DECIMAL(6,2) NULL,
  depth DECIMAL(6,2) NULL,
  base_price DECIMAL(10,2) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'available',
  has_electricity TINYINT(1) NOT NULL DEFAULT 0,
  has_roof TINYINT(1) NOT NULL DEFAULT 0,
  note VARCHAR(255) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_booths_market_code (market_id, booth_code),
  INDEX idx_booths_market_status (market_id, status),
  CONSTRAINT fk_booths_market FOREIGN KEY (market_id) REFERENCES markets(id) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 8. bookings — การจองแผง
--    status: pending | confirmed | cancelled | rejected
--    active_slot มีค่าเฉพาะการจองที่ยัง pending/confirmed (นอกนั้น NULL)
--    unique key บนคอลัมน์นี้จึงกันการจอง active ซ้อนกันในแผง/รอบเดียวกัน
--    (ใช้แทน partial unique index ซึ่ง MariaDB ไม่รองรับ)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS bookings (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  event_id INT UNSIGNED NOT NULL,
  booth_id INT UNSIGNED NOT NULL,
  shop_id INT UNSIGNED NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'confirmed',
  price_at_booking DECIMAL(10,2) NOT NULL,
  booked_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  cancelled_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  active_slot VARCHAR(30) AS (CASE WHEN status IN ('pending', 'confirmed') THEN CONCAT(event_id, ':', booth_id) END) PERSISTENT,
  INDEX idx_bookings_shop_status (shop_id, status),
  INDEX idx_bookings_event_booth_status (event_id, booth_id, status),
  UNIQUE KEY uq_bookings_active_slot (active_slot),
  CONSTRAINT fk_bookings_event FOREIGN KEY (event_id) REFERENCES market_events(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_bookings_booth FOREIGN KEY (booth_id) REFERENCES booths(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_bookings_shop FOREIGN KEY (shop_id) REFERENCES shops(id) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 9. sessions — การเข้าสู่ระบบ (เก็บเฉพาะ SHA-256 ของ token; restart server แล้วไม่หลุด)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sessions (
  token_hash CHAR(64) NOT NULL PRIMARY KEY,
  user_id INT UNSIGNED NOT NULL,
  expires_at DATETIME NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_sessions_user (user_id),
  INDEX idx_sessions_expires (expires_at),
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 10. audit_logs — ประวัติการทำงาน (ผู้ดูแลดูย้อนหลังได้ที่แท็บ "ประวัติ")
--     action เช่น auth.login, booking.created, admin.event_updated
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit_logs (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  action VARCHAR(60) NOT NULL,
  actor_user_id INT UNSIGNED NULL,
  details LONGTEXT NULL CHECK (details IS NULL OR JSON_VALID(details)),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_audit_action (action),
  INDEX idx_audit_created (created_at),
  CONSTRAINT fk_audit_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- อัปเกรดฐานข้อมูลจากเวอร์ชันก่อนหน้า (ไม่มีผลถ้ามีอยู่แล้ว)
-- ---------------------------------------------------------------------
ALTER TABLE users ADD COLUMN IF NOT EXISTS role VARCHAR(20) NOT NULL DEFAULT 'shop' AFTER password_hash;

ALTER TABLE shops
  ADD COLUMN IF NOT EXISTS category_id INT UNSIGNED NULL AFTER shop_name,
  ADD COLUMN IF NOT EXISTS contact_name VARCHAR(100) NULL AFTER description,
  ADD COLUMN IF NOT EXISTS social_url VARCHAR(255) NULL AFTER contact_phone,
  ADD COLUMN IF NOT EXISTS image_url VARCHAR(255) NULL AFTER social_url,
  ADD INDEX IF NOT EXISTS idx_shops_category_id (category_id),
  ADD CONSTRAINT fk_shops_category FOREIGN KEY IF NOT EXISTS (category_id) REFERENCES categories(id) ON DELETE RESTRICT ON UPDATE RESTRICT;

ALTER TABLE markets
  ADD COLUMN IF NOT EXISTS code VARCHAR(20) NULL AFTER id,
  ADD COLUMN IF NOT EXISTS district_id INT UNSIGNED NULL AFTER market_name,
  ADD COLUMN IF NOT EXISTS subdistrict VARCHAR(100) NULL AFTER district_id,
  ADD COLUMN IF NOT EXISTS latitude DECIMAL(9,6) NULL AFTER address,
  ADD COLUMN IF NOT EXISTS longitude DECIMAL(9,6) NULL AFTER latitude,
  ADD COLUMN IF NOT EXISTS market_type VARCHAR(30) NOT NULL DEFAULT 'weekly' AFTER longitude,
  ADD COLUMN IF NOT EXISTS open_days VARCHAR(20) NULL AFTER market_type,
  ADD COLUMN IF NOT EXISTS organizer VARCHAR(150) NULL AFTER description,
  ADD COLUMN IF NOT EXISTS contact_phone VARCHAR(20) NULL AFTER organizer,
  ADD COLUMN IF NOT EXISTS image_url VARCHAR(255) NULL AFTER contact_phone,
  ADD UNIQUE KEY IF NOT EXISTS uq_markets_code (code),
  ADD INDEX IF NOT EXISTS idx_markets_district (district_id, is_active),
  ADD CONSTRAINT fk_markets_district FOREIGN KEY IF NOT EXISTS (district_id) REFERENCES districts(id) ON DELETE RESTRICT ON UPDATE RESTRICT;

ALTER TABLE market_events ADD INDEX IF NOT EXISTS idx_events_date_status (event_date, status);

ALTER TABLE booths
  ADD COLUMN IF NOT EXISTS zone VARCHAR(50) NULL AFTER booth_code,
  ADD COLUMN IF NOT EXISTS has_electricity TINYINT(1) NOT NULL DEFAULT 0 AFTER status,
  ADD COLUMN IF NOT EXISTS has_roof TINYINT(1) NOT NULL DEFAULT 0 AFTER has_electricity,
  ADD COLUMN IF NOT EXISTS note VARCHAR(255) NULL AFTER has_roof;

-- ---------------------------------------------------------------------
-- ข้อมูลอ้างอิง: อำเภอและประเภทสินค้า (เพิ่มเฉพาะที่ยังไม่มี ไม่เขียนทับ)
-- ---------------------------------------------------------------------
