-- ย้ายประเภทสินค้าแบบข้อความของร้านเดิมไปเป็น category_id (ทำเฉพาะร้านที่ยังไม่มี category_id)
UPDATE shops s JOIN categories c ON c.name = s.category SET s.category_id = c.id WHERE s.category_id IS NULL;
UPDATE shops SET category_id = (SELECT id FROM categories WHERE name = 'อาหารปรุงสำเร็จ') WHERE category_id IS NULL AND category = 'อาหาร';
UPDATE shops SET category_id = (SELECT id FROM categories WHERE name = 'ขนมและของหวาน') WHERE category_id IS NULL AND category IN ('ขนม', 'ขนมและเครื่องดื่ม');
UPDATE shops SET category_id = (SELECT id FROM categories WHERE name = 'งานฝีมือและผ้าทอ') WHERE category_id IS NULL AND category = 'งานฝีมือ';
UPDATE shops SET category_id = (SELECT id FROM categories WHERE name = 'อื่น ๆ') WHERE category_id IS NULL AND category IS NOT NULL AND category <> '';

-- ตลาดตัวอย่างของเวอร์ชันก่อน (ที่อยู่สมมติ) ถูกซ่อนแทนการลบ — ประวัติการจองเดิมยังอยู่ครบ
-- หากต้องการใช้ต่อ ให้แก้ข้อมูลที่แท็บ "ตลาดทั้งหมด" แล้วเปิดแสดงอีกครั้ง
UPDATE markets SET is_active = 0, district_id = (SELECT id FROM districts WHERE code = '6301'), updated_at = UTC_TIMESTAMP()
WHERE market_name = 'ตลาดนัดสวนกลาง' AND address = 'ลานกิจกรรมชุมชน ถนนตัวอย่าง' AND code IS NULL AND district_id IS NULL;

-- ---------------------------------------------------------------------
-- การตั้งผู้ดูแลตลาดเพิ่มเติม (ทำด้วยมือ):
--   1) สมัครบัญชีร้านค้าตามปกติผ่านหน้าเว็บ
--   2) UPDATE users SET role = 'admin' WHERE email = 'owner@example.com';  แล้วเข้าสู่ระบบใหม่
-- ---------------------------------------------------------------------

-- >>> SEED START
-- =====================================================================
-- ข้อมูลตัวอย่างจังหวัดตาก (ใส่ครั้งเดียว) — ข้อมูลสมมติสำหรับทดลองใช้งานและสาธิต
--   24 ตลาด ใน 9 อำเภอ, 634 แผง, 489 ร้านค้า, แผงประจำ 522 แผง
--   รอบตลาดสร้างตามวันเปิดของแต่ละตลาด นับจากวันที่รัน migration (ย้อนหลัง 5 สัปดาห์ ล่วงหน้า 9 สัปดาห์;
--   ตลาดที่เปิดทุกวัน ย้อนหลัง 2 สัปดาห์ ล่วงหน้า 4 สัปดาห์) และการจองสุ่มแบบคงที่ (CRC32) ตามความถี่ของร้านประจำ
--   ชื่อร้าน ผู้ติดต่อ และเบอร์โทร (0800xxxxxx / 0810xxxxxx) เป็นข้อมูลสมมติ; ชื่อสถานที่และพิกัดเป็นค่าประมาณ
--   ต้องตรวจสอบกับข้อมูลจริงก่อนเปิดใช้งานจริง
--   บัญชีทดลอง: admin@taklad.test (ผู้ดูแล) และ shop001@taklad.test … shop489@taklad.test
--   รหัสผ่านทุกบัญชี: Taklad2026  — เปลี่ยนรหัสหรือปิดบัญชีทดลองก่อนเปิดใช้งานจริง
-- =====================================================================
SET @today := DATE(DATE_ADD(UTC_TIMESTAMP(), INTERVAL 7 HOUR));
SET @now := UTC_TIMESTAMP();
SET @seed := (SELECT COUNT(*) = 0 FROM markets WHERE code = 'TAK-MU-01');
SET @hash := '$2a$10$B.oxnqTVHiYZ6mvx.JZKU.VHhjJxHAzkeRxzX1ClQsygAdP6V3RyO';

DROP TEMPORARY TABLE IF EXISTS seed_markets, seed_booths, seed_shops, seed_vendors, seed_numbers;
CREATE TEMPORARY TABLE seed_markets (code VARCHAR(20) NOT NULL PRIMARY KEY, market_name VARCHAR(150) NOT NULL, district_code CHAR(4) NOT NULL, subdistrict VARCHAR(100), address VARCHAR(500), latitude DECIMAL(9,6), longitude DECIMAL(9,6), market_type VARCHAR(30), open_days VARCHAR(20), open_time TIME, close_time TIME, description TEXT, organizer VARCHAR(150), event_name VARCHAR(150), daily TINYINT(1), from_offset INT, to_offset INT) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE seed_booths (market_code VARCHAR(20) NOT NULL, booth_code VARCHAR(30) NOT NULL, zone VARCHAR(50), map_x DECIMAL(8,3), map_y DECIMAL(8,3), width DECIMAL(6,2), depth DECIMAL(6,2), base_price DECIMAL(10,2), status VARCHAR(20), has_electricity TINYINT(1), has_roof TINYINT(1), note VARCHAR(255), PRIMARY KEY (market_code, booth_code)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE seed_shops (email VARCHAR(255) NOT NULL PRIMARY KEY, phone VARCHAR(20), shop_name VARCHAR(150) NOT NULL, category VARCHAR(100) NOT NULL, description TEXT, contact_name VARCHAR(100), contact_phone VARCHAR(20), joined_days INT, is_active TINYINT(1)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE seed_vendors (market_code VARCHAR(20) NOT NULL, booth_code VARCHAR(30) NOT NULL, email VARCHAR(255) NOT NULL, loyalty INT NOT NULL, PRIMARY KEY (market_code, booth_code)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE seed_numbers (n INT NOT NULL PRIMARY KEY) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO seed_markets VALUES
  ('TAK-MU-01', 'ถนนคนเดินตรอกบ้านจีน', '6301', 'ระแหง', 'ถนนตากสิน ตรอกบ้านจีน ริมแม่น้ำปิง อ.เมืองตาก', 16.8697, 99.1253, 'walking_street', '6', '17:00:00', '22:00:00', 'ถนนคนเดินย่านบ้านไม้เก่าริมแม่น้ำปิง มีอาหารพื้นเมือง ขนม งานฝีมือ และดนตรีเปิดหมวกทุกเย็นวันเสาร์', 'เทศบาลเมืองตาก', 'ถนนคนเดิน', 0, -35, 63),
  ('TAK-MU-02', 'ตลาดสดเทศบาลเมืองตาก', '6301', 'หนองหลวง', 'ถนนมหาดไทยบำรุง อ.เมืองตาก', 16.8818, 99.1262, 'morning', '0,1,2,3,4,5,6', '05:00:00', '11:00:00', 'ตลาดสดประจำเมือง เปิดทุกเช้า มีผักสด เนื้อสัตว์ อาหารปรุงสำเร็จ และขนมพื้นบ้าน', 'เทศบาลเมืองตาก', 'ตลาดเช้าประจำวัน', 1, -14, 28),
  ('TAK-MU-03', 'ตลาดเย็นริมปิง', '6301', 'เชียงเงิน', 'ลานริมแม่น้ำปิง ถนนพหลโยธิน อ.เมืองตาก', 16.8905, 99.1219, 'evening', '2,5', '15:30:00', '20:00:00', 'ตลาดเย็นหลังเลิกงาน กับข้าวถุง ผักสด และของใช้ในบ้าน ทุกวันอังคารและวันศุกร์', 'เทศบาลเมืองตาก', 'ตลาดเย็น', 0, -35, 63),
  ('TAK-MU-04', 'ตลาดนัดไม้งาม', '6301', 'ไม้งาม', 'ลานหน้าที่ทำการ อบต.ไม้งาม อ.เมืองตาก', 16.9438, 99.103, 'weekly', '4', '06:00:00', '12:00:00', 'ตลาดนัดชุมชนเช้าวันพฤหัสบดี ผักจากสวนชาวบ้าน เสื้อผ้า และต้นไม้', 'องค์การบริหารส่วนตำบลไม้งาม', 'ตลาดนัด', 0, -35, 63),
  ('TAK-BT-01', 'ตลาดนัดบ้านตาก', '6302', 'ตากตก', 'ลานตลาดเทศบาลตำบลบ้านตาก อ.บ้านตาก', 17.043, 99.079, 'weekly', '1,4', '15:00:00', '19:30:00', 'ตลาดนัดเย็นวันจันทร์และวันพฤหัสบดี ของกิน ผัก และเสื้อผ้าราคาย่อมเยา', 'เทศบาลตำบลบ้านตาก', 'ตลาดนัด', 0, -35, 63),
  ('TAK-BT-02', 'ตลาดชุมชนเกาะตะเภา', '6302', 'เกาะตะเภา', 'ลานวัดเกาะตะเภา อ.บ้านตาก', 17.0835, 99.0614, 'community', '0', '06:00:00', '11:00:00', 'ตลาดชุมชนเช้าวันอาทิตย์ ขนมพื้นบ้าน ผักริมน้ำปิง และของฝากจากกลุ่มแม่บ้าน', 'กลุ่มวิสาหกิจชุมชนเกาะตะเภา', 'ตลาดชุมชน', 0, -35, 63),
  ('TAK-SN-01', 'ตลาดนัดสามเงา', '6303', 'สามเงา', 'ลานหน้าที่ว่าการอำเภอสามเงา', 17.229, 99.038, 'weekly', '3', '15:00:00', '19:00:00', 'ตลาดนัดเย็นวันพุธของคนสามเงา อาหาร ผัก และของใช้ในบ้าน', 'เทศบาลตำบลสามเงา', 'ตลาดนัด', 0, -35, 63),
  ('TAK-SN-02', 'ตลาดสุดสัปดาห์เขื่อนภูมิพล', '6303', 'สามเงา', 'ลานจอดรถจุดชมวิวสันเขื่อนภูมิพล อ.สามเงา', 17.243, 98.972, 'community', '0,6', '08:00:00', '16:00:00', 'ตลาดสำหรับนักท่องเที่ยวที่มาเที่ยวเขื่อน มีปลาแม่น้ำ ของฝาก เครื่องดื่ม และต้นไม้', 'กลุ่มผู้ค้าชุมชนเขื่อนภูมิพล', 'ตลาดสุดสัปดาห์', 0, -35, 63),
  ('TAK-MR-01', 'ตลาดสดแม่ระมาด', '6304', 'แม่ระมาด', 'ถนนสายแม่สอด–ท่าสองยาง ตัวอำเภอแม่ระมาด', 16.9849, 98.5189, 'morning', '0,1,2,3,4,5,6', '05:30:00', '11:00:00', 'ตลาดเช้าประจำอำเภอ ผักพื้นบ้าน ของสด และสินค้าจากชายแดน', 'เทศบาลตำบลแม่ระมาด', 'ตลาดเช้าประจำวัน', 1, -14, 28),
  ('TAK-MR-02', 'ตลาดนัดแม่ระมาด', '6304', 'แม่ระมาด', 'ลานกีฬาเทศบาลตำบลแม่ระมาด', 16.989, 98.515, 'weekly', '5', '15:00:00', '19:00:00', 'ตลาดนัดเย็นวันศุกร์ เสื้อผ้า ของใช้ และของกินเล่น', 'เทศบาลตำบลแม่ระมาด', 'ตลาดนัด', 0, -35, 63),
  ('TAK-TS-01', 'ตลาดนัดแม่ต้าน', '6305', 'แม่ต้าน', 'ลานตลาดบ้านแม่ต้าน อ.ท่าสองยาง', 17.2276, 98.231, 'weekly', '2', '14:00:00', '19:00:00', 'ตลาดนัดวันอังคารของอำเภอท่าสองยาง มีผ้าทอกะเหรี่ยงและผักจากบนดอย', 'เทศบาลตำบลแม่ต้าน', 'ตลาดนัด', 0, -35, 63),
  ('TAK-TS-02', 'ตลาดนัดบ้านท่าสองยาง', '6305', 'ท่าสองยาง', 'ริมแม่น้ำเมย บ้านท่าสองยาง', 17.564, 97.925, 'community', '6', '06:00:00', '12:00:00', 'ตลาดชุมชนริมแม่น้ำเมย ทางเหนือสุดของจังหวัดตาก สินค้าพื้นบ้านและของจากฝั่งเมียนมา', 'องค์การบริหารส่วนตำบลท่าสองยาง', 'ตลาดนัด', 0, -35, 63),
  ('TAK-MS-01', 'ตลาดริมเมย', '6306', 'ท่าสายลวด', 'ริมแม่น้ำเมย ใกล้สะพานมิตรภาพไทย–เมียนมา อ.แม่สอด', 16.7004, 98.5108, 'border', '0,1,2,3,4,5,6', '07:00:00', '18:00:00', 'ตลาดชายแดนที่ใหญ่ที่สุดของจังหวัด สินค้าจากเมียนมา หยก พลอย ผ้า ของแห้ง และของฝากเปิดทุกวัน', 'เทศบาลตำบลท่าสายลวด', 'ตลาดริมเมย', 1, -14, 28),
  ('TAK-MS-02', 'ตลาดสดเทศบาลนครแม่สอด', '6306', 'แม่สอด', 'ถนนประสาทวิถี ใจกลางเมืองแม่สอด', 16.7166, 98.5703, 'morning', '0,1,2,3,4,5,6', '05:00:00', '12:00:00', 'ตลาดเช้าหลายวัฒนธรรม ไทย เมียนมา และชาติพันธุ์ มีของสด ผักพื้นบ้าน และอาหารเช้าหลากหลาย', 'เทศบาลนครแม่สอด', 'ตลาดเช้าประจำวัน', 1, -14, 28),
  ('TAK-MS-03', 'ถนนคนเดินแม่สอด', '6306', 'แม่สอด', 'ถนนอินทรคีรี อ.แม่สอด', 16.715, 98.5752, 'walking_street', '6', '16:00:00', '22:00:00', 'ถนนคนเดินเย็นวันเสาร์ อาหารพื้นเมือง ชานมพม่า โรตี งานฝีมือ และเสื้อผ้าทำมือ', 'เทศบาลนครแม่สอด', 'ถนนคนเดิน', 0, -35, 63),
  ('TAK-MS-04', 'ตลาดเย็นแม่สอด', '6306', 'แม่สอด', 'ลานตลาดเย็นถนนสายเอเชีย อ.แม่สอด', 16.7292, 98.5655, 'evening', '0,3', '15:30:00', '21:00:00', 'ตลาดเย็นวันพุธและวันอาทิตย์ กับข้าว ผักสด เสื้อผ้า และของใช้', 'เทศบาลนครแม่สอด', 'ตลาดเย็น', 0, -35, 63),
  ('TAK-MS-05', 'ตลาดนัดชุมชนแม่ปะ', '6306', 'แม่ปะ', 'ลานหน้าวัดแม่ปะ อ.แม่สอด', 16.751, 98.602, 'community', '4', '06:00:00', '11:30:00', 'ตลาดชุมชนเช้าวันพฤหัสบดี ผักสวนครัว ต้นไม้ และขนมพื้นบ้าน', 'องค์การบริหารส่วนตำบลแม่ปะ', 'ตลาดนัด', 0, -35, 63),
  ('TAK-PP-01', 'ตลาดผักดอยพบพระ', '6307', 'พบพระ', 'ศูนย์รวมผักเมืองหนาว ถนนแม่สอด–อุ้มผาง อ.พบพระ', 16.392, 98.69, 'morning', '0,1,2,3,4,5,6', '04:00:00', '10:00:00', 'แหล่งรวมผักเมืองหนาวและผลไม้จากดอยพบพระ อะโวคาโด สตรอว์เบอร์รี กะหล่ำ ขายปลีกและส่งทุกเช้ามืด', 'เทศบาลตำบลพบพระ', 'ตลาดผักเช้าประจำวัน', 1, -14, 28),
  ('TAK-PP-02', 'ตลาดนัดพบพระ', '6307', 'พบพระ', 'ลานตลาดนัดตัวอำเภอพบพระ', 16.3865, 98.688, 'weekly', '3', '14:00:00', '19:00:00', 'ตลาดนัดเย็นวันพุธ อาหาร เสื้อผ้า ของใช้ และสินค้าชายแดน', 'เทศบาลตำบลพบพระ', 'ตลาดนัด', 0, -35, 63),
  ('TAK-PP-03', 'ตลาดนัดชุมชนวาเล่ย์', '6307', 'วาเล่ย์', 'บ้านวาเล่ย์ อ.พบพระ', 16.312, 98.676, 'community', '0', '07:00:00', '12:00:00', 'ตลาดชุมชนใกล้ชายแดน วันอาทิตย์ ผักพื้นบ้านและของจากฝั่งเมียนมา', 'องค์การบริหารส่วนตำบลวาเล่ย์', 'ตลาดนัด', 0, -35, 63),
  ('TAK-UP-01', 'ตลาดเช้าอุ้มผาง', '6308', 'อุ้มผาง', 'ตัวอำเภออุ้มผาง ใกล้ที่ว่าการอำเภอ', 16.018, 98.864, 'morning', '0,1,2,3,4,5,6', '05:30:00', '10:00:00', 'ตลาดเช้าเล็ก ๆ ของเมืองในหุบเขา ผักป่า ของสด และอาหารเช้าสำหรับนักท่องเที่ยวไปน้ำตกทีลอซู', 'เทศบาลตำบลอุ้มผาง', 'ตลาดเช้าประจำวัน', 1, -14, 28),
  ('TAK-UP-02', 'ถนนคนเดินอุ้มผาง', '6308', 'อุ้มผาง', 'ถนนในตัวอำเภออุ้มผาง', 16.0196, 98.8656, 'walking_street', '6', '16:00:00', '21:00:00', 'ถนนคนเดินเย็นวันเสาร์ กาแฟดอย ของฝาก ผ้าทอ และอาหารชาติพันธุ์', 'เทศบาลตำบลอุ้มผาง', 'ถนนคนเดิน', 0, -35, 63),
  ('TAK-WC-01', 'ตลาดนัดวังเจ้า', '6309', 'เชียงทอง', 'ลานตลาดนัดตำบลเชียงทอง อ.วังเจ้า', 16.679, 99.246, 'weekly', '5', '15:00:00', '19:00:00', 'ตลาดนัดเย็นวันศุกร์ริมถนนพหลโยธิน ผัก อาหาร และเสื้อผ้า', 'เทศบาลตำบลเชียงทอง', 'ตลาดนัด', 0, -35, 63),
  ('TAK-WC-02', 'ตลาดชุมชนนาโบสถ์', '6309', 'นาโบสถ์', 'ลานวัดนาโบสถ์ อ.วังเจ้า', 16.625, 99.27, 'community', '0', '06:30:00', '11:30:00', 'ตลาดชุมชนเช้าวันอาทิตย์ ผักปลอดสาร ขนมพื้นบ้าน และต้นไม้', 'กลุ่มวิสาหกิจชุมชนนาโบสถ์', 'ตลาดชุมชน', 0, -35, 63);
