INSERT INTO seed_numbers (n) SELECT a.d * 10 + b.d FROM (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11) a CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b;

START TRANSACTION;

INSERT INTO markets (code, market_name, district_id, subdistrict, address, latitude, longitude, market_type, open_days, open_time, close_time, description, organizer, is_active, created_at, updated_at)
SELECT sm.code, sm.market_name, d.id, sm.subdistrict, sm.address, sm.latitude, sm.longitude, sm.market_type, sm.open_days, sm.open_time, sm.close_time, sm.description, sm.organizer, 1, @now, @now
FROM seed_markets sm JOIN districts d ON d.code = sm.district_code
WHERE @seed;

INSERT INTO booths (market_id, booth_code, zone, map_x, map_y, width, depth, base_price, status, has_electricity, has_roof, note, created_at, updated_at)
SELECT m.id, sb.booth_code, sb.zone, sb.map_x, sb.map_y, sb.width, sb.depth, sb.base_price, sb.status, sb.has_electricity, sb.has_roof, sb.note, @now, @now
FROM seed_booths sb JOIN markets m ON m.code = sb.market_code
WHERE @seed;

INSERT INTO users (email, phone, password_hash, role, is_active, created_at, updated_at)
SELECT 'admin@taklad.test', NULL, @hash, 'admin', 1, @now - INTERVAL 400 DAY, @now - INTERVAL 400 DAY
FROM DUAL WHERE @seed AND NOT EXISTS (SELECT 1 FROM users WHERE email = 'admin@taklad.test');

INSERT INTO users (email, phone, password_hash, role, is_active, created_at, updated_at)
SELECT ss.email, ss.phone, @hash, 'shop', ss.is_active, @now - INTERVAL ss.joined_days DAY, @now - INTERVAL ss.joined_days DAY
FROM seed_shops ss
WHERE @seed;

INSERT INTO shops (user_id, shop_name, category_id, description, contact_name, contact_phone, created_at, updated_at)
SELECT u.id, ss.shop_name, c.id, ss.description, ss.contact_name, ss.contact_phone, u.created_at, u.created_at
FROM seed_shops ss JOIN users u ON u.email = ss.email JOIN categories c ON c.name = ss.category
WHERE @seed;

-- รอบตลาด: ทุกวันที่ตรงกับวันเปิด (open_days) ในช่วงของแต่ละตลาด
INSERT INTO market_events (market_id, event_name, event_date, open_time, close_time, status, created_at)
SELECT m.id,
       IF(sm.daily, sm.event_name, CONCAT(sm.event_name, 'วัน', ELT(DAYOFWEEK(t.d), 'อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'))),
       t.d, NULL, NULL,
       CASE WHEN t.d < @today THEN 'closed' WHEN t.d = @today THEN 'open' ELSE 'scheduled' END,
       LEAST(@now, TIMESTAMP(t.d - INTERVAL 60 DAY))
FROM seed_markets sm
JOIN markets m ON m.code = sm.code
JOIN (SELECT n - 42 AS offset_days, @today + INTERVAL (n - 42) DAY AS d FROM seed_numbers) t ON t.offset_days BETWEEN sm.from_offset AND sm.to_offset
WHERE @seed AND FIND_IN_SET(DAYOFWEEK(t.d) - 1, sm.open_days) > 0;

-- งดตลาด 2 รอบ: รอบที่ผ่านมาของถนนคนเดินแม่สอด (ฝนตกหนัก) และรอบที่จะถึงของตลาดเขื่อนภูมิพล
SET @past_cancel := (SELECT MAX(e.event_date) FROM market_events e JOIN markets m ON m.id = e.market_id WHERE @seed AND m.code = 'TAK-MS-03' AND e.event_date < @today - INTERVAL 7 DAY);
SET @next_cancel := (SELECT MIN(e.event_date) FROM market_events e JOIN markets m ON m.id = e.market_id WHERE @seed AND m.code = 'TAK-SN-02' AND e.event_date > @today + INTERVAL 10 DAY);
UPDATE market_events e JOIN markets m ON m.id = e.market_id
SET e.status = 'cancelled', e.event_name = CONCAT(e.event_name, ' (งดจัด: ฝนตกหนัก)')
WHERE @seed AND m.code = 'TAK-MS-03' AND e.event_date = @past_cancel;
UPDATE market_events e JOIN markets m ON m.id = e.market_id
SET e.status = 'cancelled', e.event_name = CONCAT(e.event_name, ' (งดจัด: ปรับปรุงลานจอดรถ)')
WHERE @seed AND m.code = 'TAK-SN-02' AND e.event_date = @next_cancel;

-- การจอง: ร้านประจำจองแผงเดิม โอกาสจองลดลงเมื่อรอบอยู่ไกลออกไป ~4% ยกเลิก และ ~1% ไม่อนุมัติ (รอบที่ผ่านมา)
INSERT INTO bookings (event_id, booth_id, shop_id, status, price_at_booking, booked_at, cancelled_at, created_at, updated_at)
SELECT q.event_id, q.booth_id, q.shop_id, q.status, q.price, q.booked_at,
       IF(q.status = 'cancelled', LEAST(@now, q.booked_at + INTERVAL 2 DAY), NULL),
       q.booked_at,
       IF(q.status = 'cancelled', LEAST(@now, q.booked_at + INTERVAL 2 DAY), q.booked_at)
FROM (
  SELECT e.id AS event_id, b.id AS booth_id, s.id AS shop_id, b.base_price AS price,
         CASE WHEN CRC32(CONCAT('s', e.id, '-', b.id)) % 100 < 4 THEN 'cancelled'
              WHEN e.event_date < @today AND CRC32(CONCAT('s', e.id, '-', b.id)) % 100 < 5 THEN 'rejected'
              ELSE 'confirmed' END AS status,
         LEAST(@now - INTERVAL (CRC32(CONCAT('t', e.id, '-', b.id)) % 600 + 30) MINUTE,
               TIMESTAMP(e.event_date - INTERVAL (CRC32(CONCAT('d', e.id, '-', b.id)) % 21 + 1) DAY) + INTERVAL (CRC32(CONCAT('h', e.id, '-', b.id)) % 720 + 60) MINUTE) AS booked_at
  FROM seed_vendors v
  JOIN markets m ON m.code = v.market_code
  JOIN booths b ON b.market_id = m.id AND b.booth_code = v.booth_code AND b.status = 'available'
  JOIN users u ON u.email = v.email AND u.is_active = 1
  JOIN shops s ON s.user_id = u.id
  JOIN market_events e ON e.market_id = m.id AND e.status <> 'cancelled'
  WHERE @seed AND CRC32(CONCAT('o', e.id, '-', b.id)) % 100 < CASE
        WHEN e.event_date < @today THEN v.loyalty
        WHEN e.event_date <= @today + INTERVAL 7 DAY THEN v.loyalty - 8
        WHEN e.event_date <= @today + INTERVAL 21 DAY THEN v.loyalty - 25
        WHEN e.event_date <= @today + INTERVAL 42 DAY THEN v.loyalty - 45
        ELSE v.loyalty - 65 END
) q;

COMMIT;

DROP TEMPORARY TABLE IF EXISTS seed_markets, seed_booths, seed_shops, seed_vendors, seed_numbers;
-- <<< SEED END
